function presetValue(preset: Preset, readOnly: boolean): "allow" | "ask" | undefined {
    if (preset === "allow_all") return "allow"
    if (preset === "always_ask") return "ask"
    if (preset === "ask_writes") return readOnly ? "allow" : "ask"
    return undefined
}

